let lang=(new URLSearchParams(location.search).get('lang')==='en')?'en':'es';
const embed=new URLSearchParams(location.search).get('embed')==='1';
const t=()=>T[lang];

function applyStatic(){
  document.documentElement.lang=lang;
  document.querySelectorAll('[data-i]').forEach(el=>{const v=t()[el.dataset.i];if(typeof v==='string')el.textContent=v;});
  $('b-es').classList.toggle('on',lang==='es');
  $('b-en').classList.toggle('on',lang==='en');
  if(embed){const p=document.querySelector('.lang-pill');if(p)p.style.display='none';const rb=$('reset');if(rb)rb.style.display='none';}
}

function renderGrid(){
  const star='<svg viewBox="0 0 24 24"><path d="m12 3 2.6 5.6 6.1.8-4.4 4.3 1 6.1-5.3-2.9-5.3 2.9 1-6.1L3.3 9.4l6.1-.8z"/></svg>';
  const dots='<svg viewBox="0 0 24 24"><circle cx="12" cy="5" r="1.2" fill="currentColor" stroke="none"/><circle cx="12" cy="12" r="1.2" fill="currentColor" stroke="none"/><circle cx="12" cy="19" r="1.2" fill="currentColor" stroke="none"/></svg>';
  const mini='<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="8"/><path d="M12 8v4l2.5 1.5"/></svg>'+
             '<svg viewBox="0 0 24 24"><path d="M13 2 4 14h6l-1 8 9-12h-6z"/></svg>'+
             '<svg viewBox="0 0 24 24"><rect x="5" y="11" width="14" height="9" rx="2"/><path d="M8 11V8a4 4 0 0 1 8 0v3"/></svg>';
  grid.innerHTML=t().spaces.map((s,i)=>{
    const ph=PHOTO[i]
      ? '<div class="ph" style="background-color:'+(TINT[i].startsWith('#')?TINT[i]:'#eee')+';background-image:url('+PHOTO[i]+')"></div>'
      : '<div class="ph empty" style="background:'+TINT[i]+'"><div><span class="box"><svg viewBox="0 0 24 24"><rect x="3" y="4" width="18" height="16" rx="2"/><circle cx="8.5" cy="9.5" r="1.5"/><path d="m21 16-5-5-9 9"/></svg></span><div class="t1" style="color:#fff">'+t().addImg+'</div><div class="t2" style="color:rgba(255,255,255,.75)">'+t().addImgSub+'</div></div></div>';
    return '<div class="ws" data-idx="'+i+'">'+ph+
      '<div class="meta"><div class="ia"><span class="d" style="background:'+IA[s.ia][1]+'"></span>'+IA[s.ia][0]+
      '<span class="acts">'+star+dots+'</span></div>'+
      '<div class="nm">'+s.n+'</div><div class="ago">'+s.ago+'</div></div>'+
      '<div class="foot"><span class="mi">'+mini+'</span>'+
      '<span class="cf"><span class="lb">'+t().trust+'</span><span class="sw" style="background:'+SW[s.ia]+'"><i></i></span></span></div>'+
    '</div>';
  }).join('');
}

let timers=[],playing=false;
const sleep=ms=>new Promise(r=>timers.push(setTimeout(r,ms)));
const clearAll=()=>{timers.forEach(clearTimeout);timers=[];};
const scroll=()=>{chat.scrollTop=chat.scrollHeight;};
let audRunning=false; // true when audio is driving captions

function cue(i){
  if(audRunning)return; // audio owns the captions
  const el=$('cap');
  if(i===null){el.style.opacity='0';return;}
  el.style.opacity='0';
  timers.push(setTimeout(()=>{el.innerHTML=t().subs[i];el.style.opacity='1';},180));
}

function audCue(i){
  const el=$('cap');
  el.style.opacity='0';
  setTimeout(()=>{el.innerHTML=t().subs[i];el.style.opacity='1';},180);
}

async function ghostTo(el,pause){
  const b=el.getBoundingClientRect();
  ghost.style.left=(b.left+b.width*0.5)+'px';
  ghost.style.top=(b.top+b.height*0.55)+'px';
  ghost.style.opacity='1';
  await sleep(pause||700);
}

function userMsg(txt,xref){
  const r=document.createElement('div');r.className='row user fadein';
  const x=xref?'<div class="xref"><svg viewBox="0 0 24 24"><path d="M7 17 17 7M17 7h-6M17 7v6"/></svg>'+xref+'</div>':'';
  r.innerHTML='<div class="user-bubble">'+x+'<span class="tx"></span></div>';
  r.querySelector('.tx').textContent=txt;chat.appendChild(r);scroll();return r;
}
function aiCard(who,cls){
  const r=document.createElement('div');r.className='row fadein';
  r.innerHTML='<div class="ai-card '+(cls||'')+'"><div class="ai-head"><span class="dot"></span>'+who+'</div><div class="ai-body"><p class="tw"></p></div></div>';
  chat.appendChild(r);scroll();return r;
}
async function typeText(el,txt,speed){
  el.innerHTML='';const span=document.createElement('span');el.appendChild(span);
  const cur=document.createElement('span');cur.className='cursor';el.appendChild(cur);
  for(let i=0;i<txt.length;i++){span.textContent=txt.slice(0,i+1);if(i%3===0)scroll();await sleep(speed||16);}
  return cur;
}
function sysline(txt,spin){
  const r=document.createElement('div');r.className='row mid fadein';
  r.innerHTML='<div class="sysline">'+(spin?'<span class="sp"></span>':'')+'<span></span></div>';
  r.querySelector('.sysline span:last-child').textContent=txt;chat.appendChild(r);scroll();return r;
}
async function typeComposer(txt){
  const box=$('compIn'), tx=$('compTxt'), send=$('sendBtn');
  box.classList.add('act');tx.classList.remove('plc');tx.textContent='';
  for(let i=0;i<txt.length;i++){tx.textContent=txt.slice(0,i+1);await sleep(26);}
  send.classList.add('hot');
  await sleep(500);
}
function resetComposer(){
  const box=$('compIn'), tx=$('compTxt'), send=$('sendBtn');
  box.classList.remove('act');tx.classList.add('plc');tx.textContent=t().ph;send.classList.remove('hot');
}

async function play(){
  if(playing)return;playing=true;
  clearAll();chat.innerHTML='';resetComposer();
  dash.style.display='flex';chatwrap.classList.remove('on');
  cue(null);
  document.querySelectorAll('.ws').forEach(w=>w.classList.remove('tgt'));
  $('chipAsk').classList.remove('tgt','act');
  ghost.style.opacity='0';

  const S=t().spaces, openS=S[t().openIdx], askS=S[t().askIdx];

  // 1 — dashboard: click the workspace
  cue(0);
  await sleep(900);
  const card=grid.querySelector('[data-idx="'+t().openIdx+'"]');
  await ghostTo(card,780);
  card.classList.add('tgt');
  await sleep(420);
  ghost.style.opacity='0';

  // 2 — chat opens
  dash.style.display='none';chatwrap.classList.add('on');
  $('cTitle').textContent=openS.n;
  cue(1);
  await sleep(420);
  userMsg(t().firstUser);
  await sleep(620);
  const c1=aiCard(IA[openS.ia][0].toUpperCase(), openS.ia==='codex'?'codex':'');
  const cur1=await typeText(c1.querySelector('.tw'),t().firstAI,14);
  await sleep(360);cur1.remove();

  // 3 — click "Pregunta a otro espacio"
  cue(2);
  await sleep(560);
  const chip=$('chipAsk');
  await ghostTo(chip,760);
  chip.classList.add('tgt');
  await sleep(360);
  ghost.style.opacity='0';chip.classList.remove('tgt');chip.classList.add('act');

  // 4 — space picker
  const pk=document.createElement('div');pk.className='row mid fadein';
  pk.innerHTML='<div class="picker"><div class="ph"><span class="ic-wrap"><svg viewBox="0 0 24 24"><path d="M8 10h8M8 14h5"/><path d="M21 15a2 2 0 0 1-2 2H8l-4 4V5a2 2 0 0 1 2-2h13a2 2 0 0 1 2 2z"/></svg></span>'+
    '<div><div class="tt">'+t().pickTitle+'</div><div class="st">'+t().pickSub+'</div></div></div>'+
    S.map((s,i)=>i===t().openIdx?'':'<button class="pk" data-p="'+i+'"><span class="n">'+(i<t().openIdx?i+1:i)+'</span>'+s.n+'<span class="d" style="background:'+IA[s.ia][1]+'"></span></button>').join('')+
    '<div class="cancel">'+t().cancel+'</div></div>';
  chat.appendChild(pk);scroll();

  await sleep(900);
  const pick=pk.querySelector('[data-p="'+t().askIdx+'"]');
  await ghostTo(pick,780);
  pick.classList.add('on');
  await sleep(460);
  ghost.style.opacity='0';
  pk.querySelectorAll('.pk').forEach(b=>{if(b!==pick)b.style.opacity='.32';});

  // 5 — confirm prompt
  await sleep(420);
  sysline(t().confirm(askS.n));

  // 6 — type the cross-space question, send it
  await sleep(560);
  await typeComposer(t().question);
  const send=$('sendBtn');
  await ghostTo(send,620);
  await sleep(260);
  ghost.style.opacity='0';
  resetComposer();
  userMsg(t().question,t().xrefLbl(askS.n));

  // 7 — waiting for the other space
  cue(3);
  await sleep(520);
  const wait=sysline(t().waiting(askS.n),true);
  await sleep(2100);

  // 8 — the other space answers, with ITS own context
  const r=document.createElement('div');r.className='row fadein';
  r.innerHTML='<div class="ai-card '+(openS.ia==='codex'?'codex':'')+'"><div class="ai-head"><span class="dot"></span>'+IA[openS.ia][0].toUpperCase()+'</div>'+
    '<div class="ai-body"><div class="from"><svg viewBox="0 0 24 24"><path d="M21 15a2 2 0 0 1-2 2H8l-4 4V5a2 2 0 0 1 2-2h13a2 2 0 0 1 2 2z"/></svg>'+t().fromLbl(askS.n)+'</div>'+
    '<div class="context-chips">'+t().chips.map(c=>'<span class="c">'+c+'</span>').join('')+'</div>'+
    t().answer+'</div></div>';
  chat.appendChild(r);scroll();
  wait.querySelector('.sp').remove();

  // 9 — close the loop back in the original space
  cue(4);
  await sleep(1500);
  userMsg(t().closeUser);
  await sleep(620);
  const c2=aiCard(IA[openS.ia][0].toUpperCase(), openS.ia==='codex'?'codex':'');
  c2.querySelector('.ai-body').innerHTML='<p>'+t().closeAI+'</p>';
  scroll();
  await sleep(1600);
  cue(5);
  playing=false;
}
function restart(){clearAll();playing=false;renderGrid();play();}

$('reset').addEventListener('click',restart);
$('b-es').addEventListener('click',()=>{lang='es';applyStatic();restart();});
$('b-en').addEventListener('click',()=>{lang='en';applyStatic();restart();});

applyStatic();renderGrid();
let started=false;
const io=new IntersectionObserver(es=>{es.forEach(e=>{if(e.isIntersecting&&!started){started=true;play();}});},{threshold:.2});
